JA_KEYS = {"vextir","kikja","ahrif","kjor","hraedslu","serlausnir","oryggi","gildi","lydraedi","byggd","taekifaeri","timagluggi","tollfrelsi"}
NEI_KEYS = {"fullveldi","sjavarutvegur","spurning","adlogun","ees","efnahagur","umbod","undanthagur","evra","hervaeding","ahrifaleysi","kostnadur","oafturkraeft","landbunadur","nagrannar","skyrslan","varnarsamningur"}

def load(path):
    with io.open(path, encoding="utf-8") as f:
        return json.load(f)

def save(path, data):
    with io.open(path, "w", encoding="utf-8") as f:
        json.dump(data, f, ensure_ascii=False, indent=1)
        f.write("\n")

ja = load(JA)
nei = load(NEI)
ja_ids = {v["id"] for v in ja["videos"]}
nei_ids = {v["id"] for v in nei["videos"]}

added_ja = added_nei = skipped = 0
for i, v in enumerate(NEW, 1):
    valid = JA_KEYS if v["side"] == "ja" else NEI_KEYS
    bad = [a for a in v["args"] if a not in valid]
    assert not bad, (v["id"], bad)
    if v["side"] == "ja":
        if v["id"] in ja_ids:
            skipped += 1
        else:
            ja["videos"].append(v); ja_ids.add(v["id"]); added_ja += 1
    else:
        if v["id"] in nei_ids:
            skipped += 1
        else:
            nei["videos"].append(v); nei_ids.add(v["id"]); added_nei += 1
    if i % 10 == 0:
        save(JA, ja); save(NEI, nei)

save(JA, ja); save(NEI, nei)
print("added_ja=%d added_nei=%d skipped=%d ja_total=%d nei_total=%d" % (
    added_ja, added_nei, skipped, len(ja["videos"]), len(nei["videos"])))
